def solve() -> int:
    price_per_can = 4.5
    discount_percentage = 10
    total_price = price_per_can * 2
    if total_price >= 2 * price_per_can * (1 - discount_percentage/100):
        result = total_price
    else:
        result = total_price

    return result

def solve() -> int:
