def solve() -> int:
    chicken_price = 10
    chicken_weight = 40
    if chicken_weight > 50:
      discount = 0.1 * chicken_price
      total_price = chicken_price * (1 - discount)
    else:
      total_price = chicken_weight * chicken_price
    result = total_price
    return result

def solve() -> int:
    digit_code = 4
    numbers = 0
    for i in range(1, digit_code+1):
        for j in range(1, digit_code+1):
            if i*i + j*i == 0:
                numbers += 1
    result = numbers
    return result

def solve() -> int:
    hours_worked = 10
    if hours_worked <= 8:
        pay = 9.50 * 8
    else:
        pay = 14.25 * (hours_worked - 8)
    result = pay
    return result
